pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // First call must succeed for the property to be tested
        vm.prank(caller);
        c.airDrop();
        assertEq(c.tokenBalance(caller), 20);

        // Second call: reference reverts due to reentrancy lock, buggy succeeds
        bool secondCallOk;
        vm.prank(caller);
        try c.airDrop() { secondCallOk = true; } catch { secondCallOk = false; }
        assertTrue(!secondCallOk);
    }
}

