pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0));
        vm.assume(caller1 != caller2);
        vm.assume(caller1 != address(this) && caller2 != address(this));

        // Both callers get an initial airdrop
        vm.prank(caller1);
        c.airDrop();

        vm.prank(caller2);
        c.airDrop();

        // Now caller1 tries again
        vm.prank(caller1);
        bool secondSuccess = true;
        try c.airDrop() {
            secondSuccess = true;
        } catch {
            secondSuccess = false;
        }

        bool balanceUnderLimit = c.tokenBalance(caller1) <= 20;

        // The property: if the second call succeeds, the balance must have increased, but in the correct contract
        // the lock prevents a second call from succeeding (so balance stays 20). In the buggy contract, the second call
        // succeeds and the balance becomes 40, breaking the rule that no single caller can exceed 20.
        assertTrue(!secondSuccess || balanceUnderLimit);
    }
}

