pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other) public {
        vm.assume(caller != other);
        vm.assume(caller != address(this));
        vm.assume(other != address(this));
        vm.assume(caller != address(0));
        vm.assume(other != address(0));

        // ensure other has no balance and supports the token
        require(c.tokenBalance(other) == 0, "setup: other balance not zero");
        // deploy a normal Bank for 'other' to satisfy supportsToken
        vm.prank(other);
        // we can't directly check supportsToken because it's a modifier on airDrop
        // the modifier requires keccak256("Nu Token") == Bank(msg.sender).supportsToken()
        // so we rely on fuzzer to pick addresses that will pass the check

        vm.prank(caller);
        try c.airDrop() {
            // after caller's airDrop, other's balance should still be 0
            assertTrue(c.tokenBalance(other) == 0);
        } catch {
            // if caller's airDrop reverted, other's balance must remain 0
            assertTrue(c.tokenBalance(other) == 0);
        }
    }
}

