pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _who) public {
        // 1. Keep address admissible: avoid precompile or zero edge-case that breaks non-reentrant.
        vm.assume(_who != address(0) && uint160(_who) > 1000);
        vm.assume(_who != address(this));

        // 2. Prank as the fuzzed caller and drop.
        vm.prank(_who);
        c.airDrop();

        // 3. General rule: after a single airDrop, balance >= 20.
        //    Reference: starts at 0, +20 => 20.   Bug: overflow wraps to a value < 20.
        assertTrue(c.tokenBalance(_who) >= 20);
    }
}

